#!/usr/bin/env bash
# oaf_launchintent_lib.sh -- the LAUNCH-INTENT additions of chain_v8f_launchintent.sh (PREREG_V8F_LAUNCH_INTENT, arm A at both seeds). GENERATED by gen/build_li_lib.py; never hand-edited; its sha256 is pinned INSIDE the chain.
# SOURCED by the chain right after oaf_lib.sh (this file overrides wait_predecessor). NEW FILE: oaf_lib.sh, oaf_r2_lib.sh and oaf_dagoaccorc_r2_lib.sh are not touched.
# Needs from the chain: B L PY LCHECKS AFTER_OUT REPDIR OACC_DIR M2B_SHA BANK1_SHA WACC WINDOW_SHA and oaf_lib.sh's stop.
# EVERY MARKER, LOCK AND DONE-FILE THIS CHAIN READS OR WRITES IS NAMED FOR THIS CHAIN (launchintent), except BOX2_BUSY.txt, which is the box's ONE shared lock BY DESIGN and is taken noclobber. MEASURED 2026-10-28: the DAG-ORC r2 chain read
# DAG-OACC r2's r2_aside_done.txt (same runs root) as its own and skipped its aside (raw/2026-10-28-dag-orc-r2a/R2A_NOTE.md): two chains that write the same marker into one directory share one marker. This chain writes none of the siblings' names.

claim_box2() {   # claim_box2 <marker text>: 0 = BOX2_BUSY.txt taken (BUSY_TAKEN=1). 1 = it exists (the STOP marker is printed; nothing is removed, BUSY_TAKEN stays 0, so stop() will not release a lock this chain does not hold)
  if ( set -C; printf '%s\n' "$1" > "$B/BOX2_BUSY.txt" ) 2>/dev/null; then BUSY_TAKEN=1; return 0; fi
  echo "ZZV8FMINI-STOP busy marker present: $(cat "$B/BOX2_BUSY.txt" 2>/dev/null)"
  return 1
}

wait_predecessor() {   # OVERRIDES oaf_lib.sh's. GO only when AFTER_OUT (the DAG-ORC r2 chain's log) ENDED in its DONE marker (nothing after it, one DONE, no STOP, no guard stop, no disk-floor stop, the four runs pulled, run-record and K-REACH PASS for each)
                       # and BOX2_BUSY is released (pred-verdict-li). BUSY: re-check a few times, then HALT. WAIT: poll (OAF_POLL_S = 300 s). HALT: stop, nothing taken.
  local v w k=0 poll=${OAF_POLL_S:-300} grace=${OAF_GRACE_S:-20}
  echo "$(date '+%m-%d %H:%M') waiting for the DAG-ORC r2 chain ($AFTER_OUT: GO only when it ENDED in its DONE marker; log present: $([ -f "$AFTER_OUT" ] && echo yes || echo NO))"
  while :; do
    v=$($PY "$(cygpath -m $LCHECKS)" pred-verdict-li --out "$(cygpath -m "$AFTER_OUT")" --busy "$(cygpath -m "$B/BOX2_BUSY.txt")"); w=${v%% *}
    case $w in
      GO) echo "$(date '+%m-%d %H:%M') predecessor verdict: $v"; return 0 ;;
      HALT) stop "predecessor verdict: $v" ;;
      BUSY) k=$((k+1)); [ $k -gt 3 ] && stop "predecessor verdict: $v (still held after $k checks)"; sleep $grace ;;
      WAIT) k=0; sleep $poll ;;
      *) stop "pred-verdict-li printed no verdict ('$v')" ;;
    esac
  done
}

rep_licence_one() {   # rep_licence_one <seed>: prints the verdict line; rc 0 = PASS (conditions 1 and 2)
  local s=$1
  $PY "$(cygpath -m $LCHECKS)" rep-licence --rep-dir "$(cygpath -m "$REPDIR/M2b_s${s}_dagoaccorcrep")" --oacc-dir "$(cygpath -m "$OACC_DIR/M2b_s${s}_dagoacc")" --seed $s --init-sha ${M2B_SHA[$s]} --bank-sha ${BANK1_SHA[$s]} \
      --w-acc $WACC --window-sha $WINDOW_SHA ${AFTER_OUT:+--log "$(cygpath -m "$AFTER_OUT")"}
}

rep_licence_all() {   # rep_licence_all: BOTH seeds; rc 0 only if both PASS. A failure means REP must be trained anew (2 runs, about 1.4 h) before any LAUNCH-INTENT row is read: this chain does not build that, it STOPs.
  local s bad=0
  for s in 0 1; do rep_licence_one $s || bad=1; done
  [ $bad = 0 ]
}
